import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { requireWrite } from "@/lib/auth/user";
import { getSettings, setSettings } from "@/lib/db/settings";
import { exportAll } from "@/lib/db/json-export";
import { PreviewLink } from "../ui/preview-link";
import { SavePreview } from "../ui/save-preview";
import * as s from "../ui/styles";

const SETTINGS_KEYS = [
  "phone",
  "kakao_id",
  "sms_number",
  "address",
  "address_detail",
  "business_hours",
  "slogan",
  "slogan_sub",
  "slogan_en",
  "copyright",
  "sns_instagram",
  "sns_youtube",
  "sns_blog",
  "sns_kakao_channel",
  "terms",
  "privacy_policy",
];

export default async function SettingsPage({
  searchParams,
}: {
  searchParams: Promise<{ msg?: string; error?: string }>;
}) {
  await requireWrite();
  const sp = await searchParams;
  const settings = getSettings(SETTINGS_KEYS);

  async function saveAction(formData: FormData) {
    "use server";
    await requireWrite();
    const entries: Record<string, string> = {};
    for (const key of SETTINGS_KEYS) {
      entries[key] = String(formData.get(key) ?? "").trim();
    }
    setSettings(entries);

    // 설정 변경 시 모든 JSON에 contact 정보가 반영되므로 전체 재생성
    try { exportAll(); } catch (e) { console.error("[settings] exportAll:", e); }

    revalidatePath("/admin/settings");
    redirect("/admin/settings?msg=saved");
  }

  return (
    <div className="mx-auto max-w-[800px]">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold text-[#231F20]">설정</h1>
          <p className="mt-1 text-sm text-[#9E9F9C]">사이트 기본 정보 관리. 저장하면 모든 페이지 하단 연락처에 반영됩니다.</p>
        </div>
        <PreviewLink path="/" label="사이트 보기" />
      </div>

      {sp.msg === "saved" && <div className={`mt-4 ${s.okBox}`}>저장되었습니다. 모든 페이지 하단에 즉시 반영됩니다.</div>}
      {sp.error && <div className={`mt-4 ${s.errorBox}`}>{sp.error}</div>}
      <SavePreview previewPath="/" saved={sp.msg === "saved"} />

      <form action={saveAction} className="mt-6 space-y-6">
        {/* 연락처 */}
        <fieldset className="space-y-4 rounded-lg border border-[#E5E7EA] bg-white p-5">
          <legend className="text-sm font-bold text-[#231F20]">연락처</legend>

          <div className="space-y-1.5">
            <label htmlFor="phone" className={s.label}>대표 전화번호</label>
            <input id="phone" name="phone" defaultValue={settings.phone ?? "010-4708-6091"} className={s.input} />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="kakao_id" className={s.label}>카카오톡 ID</label>
            <input id="kakao_id" name="kakao_id" defaultValue={settings.kakao_id ?? ""} className={s.input} />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="sms_number" className={s.label}>SMS 수신 번호</label>
            <input id="sms_number" name="sms_number" defaultValue={settings.sms_number ?? ""} className={s.input} />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="address" className={s.label}>주소</label>
            <input id="address" name="address" defaultValue={settings.address ?? "서울시 종로구 종로 191, 2층"} className={s.input} />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="address_detail" className={s.label}>주소 부가정보</label>
            <input id="address_detail" name="address_detail" defaultValue={settings.address_detail ?? "(종로5가역 12번출구)"} className={s.input} placeholder="(종로5가역 12번출구)" />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="business_hours" className={s.label}>영업시간</label>
            <input id="business_hours" name="business_hours" defaultValue={settings.business_hours ?? "평일 09:00 ~ 18:00"} className={s.input} />
          </div>
        </fieldset>

        {/* 브랜드 텍스트 */}
        <fieldset className="space-y-4 rounded-lg border border-[#E5E7EA] bg-white p-5">
          <legend className="text-sm font-bold text-[#231F20]">브랜드 텍스트</legend>
          <p className="text-xs text-[#9E9F9C]">사이트 전체 푸터·공통 영역에 표시되는 슬로건과 저작권 문구입니다.</p>

          <div className="space-y-1.5">
            <label htmlFor="slogan" className={s.label}>슬로건 (1줄)</label>
            <input id="slogan" name="slogan" defaultValue={settings.slogan ?? "당구, 그 이상의 가치!"} className={s.input} />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="slogan_sub" className={s.label}>서브 슬로건 (2줄)</label>
            <input id="slogan_sub" name="slogan_sub" defaultValue={settings.slogan_sub ?? "함께 만드는 성공 스토리"} className={s.input} />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="slogan_en" className={s.label}>영문 슬로건</label>
            <input id="slogan_en" name="slogan_en" defaultValue={settings.slogan_en ?? "Premium Billiards Life"} className={s.input} />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="copyright" className={s.label}>저작권 문구</label>
            <input id="copyright" name="copyright" defaultValue={settings.copyright ?? "© 2025 HI Q BILLIARDS. All rights reserved."} className={s.input} />
          </div>
        </fieldset>

        {/* SNS 링크 */}
        <fieldset className="space-y-4 rounded-lg border border-[#E5E7EA] bg-white p-5">
          <legend className="text-sm font-bold text-[#231F20]">SNS 링크</legend>
          <p className="text-xs text-[#9E9F9C]">각 항목에 전체 URL을 입력하세요. 비워두면 해당 링크가 사이트에서 숨겨집니다.</p>

          <div className="space-y-1.5">
            <label htmlFor="sns_kakao_channel" className={s.label}>카카오톡 오픈채팅</label>
            <input id="sns_kakao_channel" name="sns_kakao_channel" defaultValue={settings.sns_kakao_channel ?? ""} className={s.input} placeholder="https://open.kakao.com/o/..." />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="sns_instagram" className={s.label}>인스타그램</label>
            <input id="sns_instagram" name="sns_instagram" defaultValue={settings.sns_instagram ?? ""} className={s.input} placeholder="https://www.instagram.com/..." />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="sns_youtube" className={s.label}>유튜브</label>
            <input id="sns_youtube" name="sns_youtube" defaultValue={settings.sns_youtube ?? ""} className={s.input} placeholder="https://www.youtube.com/..." />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="sns_blog" className={s.label}>블로그</label>
            <input id="sns_blog" name="sns_blog" defaultValue={settings.sns_blog ?? ""} className={s.input} placeholder="https://blog.naver.com/..." />
          </div>
        </fieldset>

        {/* 약관 */}
        <fieldset className="space-y-4 rounded-lg border border-[#E5E7EA] bg-white p-5">
          <legend className="text-sm font-bold text-[#231F20]">약관</legend>

          <div className="space-y-1.5">
            <label htmlFor="terms" className={s.label}>이용약관</label>
            <textarea id="terms" name="terms" rows={8} defaultValue={settings.terms ?? ""} className={s.textarea} />
          </div>

          <div className="space-y-1.5">
            <label htmlFor="privacy_policy" className={s.label}>개인정보처리방침</label>
            <textarea id="privacy_policy" name="privacy_policy" rows={8} defaultValue={settings.privacy_policy ?? ""} className={s.textarea} />
          </div>
        </fieldset>

        <div className="flex justify-end">
          <button type="submit" className={s.btnPrimary}>저장</button>
        </div>
      </form>
    </div>
  );
}
